import test from 'node:test';import assert from 'node:assert/strict';
import {newGame,newReturningGame,restore,save} from './simulation.js';
import {registrationCourses,registeredCourseIds,registrationProblems,confirmRegistration,timetable} from './timetable.js';
import {attendLesson} from './classes.js';
test('returning opening requires registration while old saves retain the default timetable',()=>{const s=newReturningGame();assert.equal(s.academics.registrationPending,true);assert.equal(s.clock.minute,540);assert.equal(timetable(newGame()).length,2);assert.deepEqual(timetable(restore(save(newGame()))),timetable(newGame()));});
test('selected elective replaces actual class, survives save and governs attendance',()=>{let s=newReturningGame(),ids=registeredCourseIds(s).filter(x=>x!=='1:theory');ids.push('1:coding');s=confirmRegistration(s,ids);s=restore(save(s));assert.ok(timetable(s).some(x=>x.id==='coding'));assert.ok(!timetable(s).some(x=>x.id==='theory'));const c=timetable(s).find(x=>x.id==='coding');s.clock.minute=c.start;s.location=c.location;s.buildingArea={place:c.location,id:c.area};s.academics.records['1:taei:ensemble']={status:'absent'};s=attendLesson(s,c.key,c.choices[0].id).state;assert.equal(s.academics.records[c.key].status,'present');});
test('overlap, missing required subjects and unknown IDs cannot be confirmed',()=>{const s=newReturningGame(),ids=registeredCourseIds(s);assert.throws(()=>confirmRegistration(s,[...ids,'1:coding']));assert.throws(()=>confirmRegistration(s,ids.filter(x=>x!=='2:vocal')));assert.throws(()=>confirmRegistration(s,[...ids,'not-a-course']));assert.equal(s.academics.registrationPending,true);});
test('elapsed courses cannot be dropped retroactively; future courses can change',()=>{let s=confirmRegistration(newReturningGame(),registeredCourseIds(newGame()));s.clock.minute=790;assert.throws(()=>confirmRegistration(s,registeredCourseIds(s).filter(x=>x!=='1:theory')));const ids=registeredCourseIds(s).filter(x=>x!=='2:expression');ids.push('2:film');const next=confirmRegistration(s,ids);assert.equal(next.clock.minute,790);assert.ok(timetable(next,'taei',2).some(c=>c.id==='film'));assert.deepEqual(timetable(next,'seoyeon',2),timetable(s,'seoyeon',2));});
